var i=`1195-tamales-colorados`;var t=`world-1195`;var n=`GT`;var o=`central-america-caribbean`;var r=8;var s=115;var l={en:`Tamales Colorados`,ua:`Червоні тамалес`};var d={en:`Tamales Colorados is a dish from Guatemala prepared with masa harina, chicken thigh, tomato, achiote paste. This is a home-scale version with measured ingredients in the individual steps where they are used. Banana leaves are used for Guatemalan red tamales, as in many traditional regional versions.`,ua:`Червоні тамалес, страва кухні країни Гватемала, яку готують із таких продуктів: маса харіна, куряче стегно, помідор, паста ачіоте. Кількості в домашньому рецепті прив’язані до окремих етапів приготування. Гватемальські червоні тамалес загортають у бананове листя, як у багатьох традиційних версіях.`};var m=[{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:13,i:[[`masa-harina`,550,`g`],[`lard`,150,`g`],[`chicken-stock`,500,`ml`],[`table-salt`,8,`g`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 10 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 10 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:10,i:[[`chicken-thigh`,600,`g`],[`tomato`,300,`g`],[`achiote-paste`,45,`g`]]},{en:`Place a portion of prepared filling on each leaf or wrapper, tuck in the sides and roll tightly into neat parcels.`,ua:`Викладіть порцію готової начинки на кожен листок або обгортку, загорніть боки й скрутіть щільні акуратні рулетики.`,t:[`rolling-stuffed-food`],m:17,i:[[`banana-leaf`,9,`leaf`]]},{en:`Steam the already prepared parcels or mixture over gently boiling water for approximately 75 minutes, until fully cooked or set.`,ua:`Готуйте раніше підготовлені згортки або масу на парі над слабким кипінням близько 75 хвилин до готовності.`,t:[`steaming`],m:75,i:[]}];var h={slug:i,id:t,country:`GT`,region:o,servings:8,minutes:115,title:l,text:d,steps:m};export{n as country,h as default,t as id,s as minutes,o as region,r as servings,i as slug,m as steps,d as text,l as title};